-- Compound operators share one precedence and associate LEFT.
SELECT 2.0 UNION ALL SELECT 2 UNION SELECT 3;
SELECT count(*) FROM (SELECT 3 UNION SELECT 2.0 UNION ALL SELECT 2);
SELECT 1 UNION SELECT 2 INTERSECT SELECT 2;
SELECT 1 UNION ALL SELECT 1 EXCEPT SELECT 2;
VALUES(1),(2),(3) EXCEPT VALUES(2) EXCEPT VALUES(3);
SELECT 1 EXCEPT SELECT 1 UNION SELECT 1;
SELECT 2 UNION VALUES(1),(2);
SELECT 2 UNION ALL VALUES(1),(2) UNION SELECT 5;
/*ordered*/ SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 ORDER BY 1 DESC;
SELECT 1 a UNION SELECT 2 INTERSECT SELECT 1 ORDER BY a;
SELECT count(*) FROM (SELECT 1 UNION ALL SELECT 1 UNION SELECT 1 UNION ALL SELECT 1);
SELECT x FROM (SELECT 1 x UNION SELECT 2 EXCEPT SELECT 1);
-- A recursive CTE with TWO initial arms: only the LAST arm recurses.
/*ordered*/ WITH RECURSIVE r(n) AS (SELECT 1 UNION ALL SELECT 10 UNION ALL SELECT n+1 FROM r WHERE n < 3 OR (n >= 10 AND n < 12)) SELECT n FROM r ORDER BY n;
-- Constant-valued ORDER BY subqueries are sort keys, not ordinals.
CREATE TABLE o(a INTEGER, b TEXT);
INSERT INTO o VALUES(3,'x'),(1,'y'),(2,'z');
/*ordered*/ SELECT a FROM o ORDER BY (SELECT 1);
/*ordered*/ SELECT a FROM o ORDER BY (SELECT 5);
/*ordered*/ SELECT a, b FROM o ORDER BY (SELECT 2), a;
/*ordered*/ SELECT a FROM o ORDER BY (SELECT 1) DESC, a;
